package com.example.aitmk.controller.v2;
import com.example.aitmk.model.api.v2.V2Api.*;import com.example.aitmk.security.auth.CurrentUser;import com.example.aitmk.service.v2.RealtimeEventService;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v2/realtime/events") @RequiredArgsConstructor public class RealtimeV2Controller{private final RealtimeEventService events;@GetMapping public Response<CursorPage<EventView>> get(@RequestParam(required=false)String afterEventId,@RequestParam(required=false)Integer limit,@RequestParam(required=false)Integer size){int requested=limit!=null?limit:size!=null?size:100;return Response.ok(events.recover(CurrentUser.get().getAccountRowId(),afterEventId,requested));}}
